def _area_call(controller, name, *args, **kwargs):
    """Call ``controller.<name>(...)`` if it has it -- the QC plot area's
    helpers (Step 3 plot pass P2) are reached through here, so the
    curated-method test harnesses that bind only part of the controller
    keep running a path that now also refreshes the area.  A failure is
    printed, never raised into the caller's pipeline."""
    fn = getattr(controller, name, None)
    if not callable(fn):
        # A name the controller CLASS does not have is a typo, never a
        # harness gap: say so loudly instead of dropping the call.
        if not callable(getattr(FusionReconstructionController, name, None)):
            raise AttributeError(
                f"_area_call: FusionReconstructionController has no {name!r}")
        return None          # a test fake that binds part of the class
    try:
        return fn(*args, **kwargs)
    except Exception as exc:
        print(f"[QC-AREA] {name} failed: {exc!r}")
        return None


def _unwrap_proxy(obj, max_hops: int = 8):
    """The object behind napari's ``PublicOnlyProxy`` (a ``wrapt`` proxy:
    ``__wrapped__``).  A plugin's ``viewer`` is one, and every
    ``viewer.layers[name]`` / ``layer.colormap`` read through it is a NEW
    wrapper, so identity checks must look behind it (Step 3 plot pass P3,
    live driver 2026-10-06).  At most ``max_hops`` hops."""
    for _ in range(max_hops):
        inner = getattr(obj, "__wrapped__", None)
        if inner is None or inner is obj:
            return obj
        obj = inner
    return obj


#: Job threads still running when shutdown()'s join gave up, kept alive with
#: their worker so Python never deletes a running QThread at finalization
#: ("QThread: Destroyed while thread is still running").  Step 4's pattern.
_LIVE_STEP3_THREADS: set = set()

#: The signals _RefinementTrainingWorker / _ExtractionWorker declare, cut by
#: shutdown() after it asks the worker to stop (a parity test holds them to
#: the classes).
_REFINEMENT_WORKER_SIGNALS = ("epoch_update", "finished", "error", "log", "cancelled")
_EXTRACTION_WORKER_SIGNALS = ("progress", "finished", "error", "log", "cancelled")


def _disconnect_worker_signals(worker, names) -> None:
    """Disconnect every slot from each named signal of *worker* (shutdown()).

    A copy of Step 4's ``_disconnect_all_signals`` idea, by name: dropping
    the connection drops a call already queued through it, so a worker that
    answers a cancel after ui.destroyed never reaches a handler that writes
    to the deleted UI.  Each disconnect in its own try."""
    for name in names:
        sig = getattr(worker, name, None)
        if sig is None:
            continue
        try:
            sig.disconnect()
        except Exception:
            pass


def _newest_recon_manifest(root) -> Optional[dict]:
    """The newest per-patch ``<root>/*/manifest.json`` with a
    ``recon_config``, as ``{"recon_config", "seg_config", "manifest_version",
    "cell_width_um", "path"}``, or None.  Only the direct children of *root* are read, so the
    default run's flat ``runs/`` never picks up a named run's nested
    reconstructions.  Never raises."""
    best = None
    try:
        candidates = list(Path(root).glob("*/manifest.json"))
    except Exception:      # noqa: BLE001
        return None
    for path in candidates:
        try:
            mtime = path.stat().st_mtime
            data = json.loads(path.read_text(encoding="utf-8"))
        except (OSError, ValueError):
            continue
        rc = data.get("recon_config") if isinstance(data, dict) else None
        if not isinstance(rc, dict):
            continue
        if best is None or mtime > best[0]:
            best = (mtime, path, data)
    if best is None:
        return None
    data = best[2]
    seg = data.get("seg_config")
    return {"recon_config": data["recon_config"],
            "seg_config": seg if isinstance(seg, dict) else {},
            "manifest_version": data.get("manifest_version"),
            # R2c / R2b: the cell width the user typed (µm), recorded by
            # Step 3's Reconstruct beside the per-patch pixel ``diameter``
            "cell_width_um": data.get("cell_width_um"),
            "path": str(best[1])}


def _extract_autosave_will_run(controller, patch_name) -> bool:
    """Will ``_on_qc_extract_finished`` rewrite the patch's CSV (the
    re-extract auto-save)?  Only when its guards pass -- the same run epoch,
    the patch in view (or none) -- and a table is in memory (A2 fold).
    Module-level so the harnesses that bind a subset of methods resolve
    it."""
    launch = getattr(controller, "_qc_extract_launch_epoch", None)
    if launch is not None and launch != getattr(controller, "_run_epoch", 0):
        return False
    active = getattr(controller, "_qc_view_patch_name", "") or ""
    if patch_name and active and patch_name != active:
        return False
    return getattr(controller, "_qc_features_df", None) is not None


def _active_qc_patch(controller) -> str:
    """The patch an action works on (A2 fold): the patch whose QC table is
    in memory (``_qc_view_patch_name``) FIRST, then the Curation selection,
    then the Session highlight -- the rule Save always used.  A Session
    click no longer reloads the table, and every rebuild of the Curation
    list drops its selection, so "Curation or Session" alone could name the
    Session highlight while the table, the layers and the viewer show
    another patch.  Module-level (as ``_active_run_path_id``) so the test
    harnesses that bind a subset of the controller's methods resolve it."""
    name = getattr(controller, "_qc_view_patch_name", "") or ""
    if name:
        return name
    for getter in ("_selected_curation_patch", "_selected_patch_name"):
        fn = getattr(controller, getter, None)
        if callable(fn):
            name = fn() or ""
            if name:
                return name
    return ""


def _active_run_path_id(controller) -> Optional[str]:
    """Resolve the active run's path-id for the per-run ``_paths`` helpers.

    Option A (default run = flat layout, zero migration): the DEFAULT run
    uses today's FLAT paths, so its path-id is ``None`` (→ the flat
    ``artifacts/step3/...`` sub-tree); NAMED runs return their slug (→
    ``artifacts/step3/runs/{slug}/...``).  Every per-run ``_paths`` call
    in this controller threads this through as ``run_id=...`` so
    reads/writes route to the ACTIVE run's tree while existing/default
    workspaces stay byte-identical to today.

    Implemented as a module-level function (rather than only a method) so
    it resolves defensively from ANY controller-like object — including
    the minimal ``SimpleNamespace`` / harness fakes used throughout the
    test-suite that bind only a curated subset of controller methods.  A
    missing / partial ``state_manager`` falls back to the default run
    (``None`` → flat), which is the byte-identical-to-today path.
    """
    sm = getattr(controller, "state_manager", None)
    get = getattr(sm, "get_active_run_id", None)
    if not callable(get):
        return None
    rid = get()
    # A run path-id must be a real string slug.  Anything else — None, or a
    # ``MagicMock`` from a test fake's mocked state_manager — resolves to the
    # default run (flat layout), the byte-identical-to-today path.
    if not isinstance(rid, str):
        return None
    if rid == _migrate_step3_runs.DEFAULT_RUN_ID:
        # Default run is FLAT (None) by default — byte-identical to today.
        # EXCEPTION (Phase 7): a workspace that ran the optional "Convert to
        # unified layout" migration nests the default run under
        # ``runs/default/...`` and the flag ``default_run_nested`` is True →
        # resolve to the "default" slug so reads/writes route to the nested
        # tree.  Read the flag with a strict ``is True`` so a MagicMock
        # state_manager (truthy mock return) stays on the flat path.
        getf = getattr(sm, "get_default_run_nested", None)
        if callable(getf):
            try:
                if getf() is True:
                    return _migrate_step3_runs.DEFAULT_RUN_ID
            except Exception:
                pass
        return None
    return rid



# ---------------------------------------------------------------------------
# Atomic TIFF write helper
# ---------------------------------------------------------------------------

def _atomic_tiff_write(path, data: np.ndarray, dtype=None) -> None:
    """Write a TIFF atomically via tempfile + os.replace.

    Prevents data corruption if the process is killed mid-write.
    The temporary file is created in the same directory as *path*
    so that ``os.replace`` is an atomic rename on the same filesystem.

    Phase A #3 (perf push 2026-05-09): optional ``dtype=`` kwarg
    moves the dtype-conversion responsibility into this helper.
    Callers that previously did
    ``_atomic_tiff_write(p, arr.astype(np.uint32))`` should switch to
    ``_atomic_tiff_write(p, arr, dtype=np.uint32)``.  Internally we
    use ``astype(dtype, copy=False)`` so when the input array already
    has the target dtype the conversion is a no-op (no intermediate
    copy).  Backwards-compat: ``dtype=None`` writes the array's
    native dtype, matching the pre-fix behavior.

    See commit message for full hydra-check trace.
    """
    import tempfile
    import tifffile

    if dtype is not None:
        data = np.asarray(data).astype(dtype, copy=False)

    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, tmp_path = tempfile.mkstemp(suffix=".tif", dir=str(path.parent))
    os.close(fd)
    try:
        tifffile.imwrite(tmp_path, data, bigtiff=True)
        os.replace(tmp_path, str(path))
    except BaseException:
        # Clean up partial temp file on any failure (including KeyboardInterrupt)
        try:
            os.remove(tmp_path)
        except OSError:
            pass
        raise


def _commit_triage_persist(
    *,
    df,
    garbage_ids,
    lifted_mask,
    labels_path,
    csv_path,
    csv_dir,
):
    """PURE (no Qt, no ``self``) transactional persist for Commit Triage.

    Runs steps 4–5 of the legacy ``_commit_triage_single_patch`` VERBATIM —
    stage-then-promote so the on-disk mask + CSV never diverge:

        4. Build the triage map from ``active_rows(df)`` (ghosts excluded) +
           the discarded garbage ids.
        5a. Stage the CSV to a tempfile in ``csv_dir`` via ``df.to_csv`` (NOT
            ``save_patch_csv`` — kept as a direct ``to_csv`` so the existing
            CSV-failure tests that patch ``pd.DataFrame.to_csv`` still bite).
        5b. Write the (already-lifted) mask via ``_atomic_tiff_write``.
        5c. Promote the staged CSV via ``os.replace`` AFTER the mask write.

    Transactional invariants (tested):
      * If CSV staging fails → mask is NEVER written; no orphaned temp file.
      * If the mask write fails → the staged CSV is removed (no orphan), CSV
        NOT promoted.
      * If the promote fails → the staged CSV is removed (no orphan).
      * The mask write ALWAYS happens on the success path, even with zero
        garbage (the lifted_mask is whatever the layer held).

    This is the function BOTH the background worker and the synchronous tests
    call (same approach the QC-extraction subprocess used with
    ``run_full_qc_extraction``) — so the transactional assertions are validated
    without a live QThread.

    Args:
        df: the QC features DataFrame to persist (already mutated on the main
            thread: garbage rows flipped to ``label_status="deleted"``).  A
            COPY is recommended at the call site so the worker never shares a
            mutable handle with the live controller df.
        garbage_ids: set of discarded label ids (for the triage map +
            log message).
        lifted_mask: the full-res-lifted ndarray to write (computed on the
            main thread via ``_maybe_lift_for_save`` so the worker never
            touches the live napari layer).  May be ``None`` → mask write is
            skipped and ``mask_skipped`` is reported.
        labels_path: on-disk TIFF path for the label volume (may be falsy →
            mask write skipped).
        csv_path: final CSV path to promote the staged CSV to.
        csv_dir: directory for the CSV (also the tempfile staging dir — same
            filesystem so ``os.replace`` is atomic).

    Returns:
        dict result describing exactly which step (if any) failed so the
        main-thread handler can reproduce the legacy transactional UI
        branches.  Keys:
          ``ok`` (bool): True iff every required persist step succeeded.
          ``stage`` (str): which step the outcome refers to — one of
            ``"csv_stage"``, ``"mask"``, ``"promote"``, ``"done"``.
          ``error`` (str|None): human-readable failure reason, else None.
          ``triage_map`` (dict): label-id (str) → tier, the map to hand to
            ``state_manager.set_patch_status(qc_triage=...)`` on success.
          ``mask_skipped`` (bool): True if the mask write was skipped because
            no labels_path / mask was available (NOT a failure — matches the
            legacy ``mask_saved`` flow where a missing path keeps dirty flags).
          ``csv_path`` (str): echoed back for the log line.
          ``n_garbage`` (int), ``n_labels`` (int): for the success log line.
    """
    import os as _os
    import tempfile as _tempfile
    from pathlib import Path as _Path
    from .qc_features import active_rows

    result = {
        "ok": False,
        "stage": "csv_stage",
        "error": None,
        "triage_map": {},
        "mask_skipped": False,
        "csv_path": str(csv_path),
        "n_garbage": len(garbage_ids),
        "n_labels": int(len(df)) if df is not None else 0,
    }

    # 4. Build triage map from active rows only (ghosts excluded).
    triage = {}
    for _, row in active_rows(df).iterrows():
        triage[str(int(row["label"]))] = row.get("qc_tier", "good")
    for gid in garbage_ids:
        triage[str(gid)] = "discarded"
    result["triage_map"] = triage

    csv_dir = _Path(csv_dir)
    csv_dir.mkdir(parents=True, exist_ok=True)

    # 5a. Stage CSV to a temp file (direct to_csv — NOT save_patch_csv).
    csv_staging = None
    try:
        fd, csv_staging = _tempfile.mkstemp(suffix=".csv", dir=str(csv_dir))
        _os.close(fd)
        df.to_csv(csv_staging, index=False)
    except Exception as exc:
        if csv_staging:
            try:
                _os.remove(csv_staging)
            except OSError:
                pass
        result["stage"] = "csv_stage"
        result["error"] = f"Failed to stage QC CSV: {exc}"
        return result

    # 5b. Persist label volume (already lifted on the main thread).
    mask_saved = False
    if labels_path and lifted_mask is not None:
        try:
            _atomic_tiff_write(labels_path, lifted_mask, dtype=np.uint32)
            mask_saved = True
        except Exception as exc:
            result["stage"] = "mask"
            result["error"] = f"Failed to save label volume: {exc}"
            # Mask failed — discard staged CSV, no promote.
            try:
                _os.remove(csv_staging)
            except OSError:
                pass
            return result

    if not mask_saved:
        # No labels_path / no mask → skip mask write entirely.  Legacy flow
        # keeps dirty flags True (mask not persisted).  Discard staged CSV so
        # CSV + mask never diverge.
        result["stage"] = "mask"
        result["mask_skipped"] = True
        result["error"] = "label volume not written (no path / mask)"
        try:
            _os.remove(csv_staging)
        except OSError:
            pass
        return result

    # 5c. Both writes succeeded — promote staged CSV (A2 fold: retried
    # while a reader holds the CSV open on Windows).
    from .qc_features import replace_with_retry
    try:
        replace_with_retry(csv_staging, str(csv_path))
    except Exception as exc:
        result["stage"] = "promote"
        result["error"] = f"CSV promote failed: {exc}"
        try:
            _os.remove(csv_staging)
        except OSError:
            pass
        return result

    result["ok"] = True
    result["stage"] = "done"
    return result


def _save_curation_persist(
    *,
    lifted_mask,
    labels_path,
    csv_df,
    csv_path,
    save_patch_csv,
):
    """PURE (no Qt, no ``self``) transactional persist for Save Curation.

    Holds the threadable steps of the legacy ``_save_curation`` VERBATIM —
    the stage-then-promote strategy that keeps the on-disk mask + CSV from
    diverging while leaving the ORIGINAL intact until a full success:

        A. Write the (already-lifted) mask to a ``<labels>.tif.saving``
           STAGING path via ``_atomic_tiff_write`` (original untouched).
        B. Mask-only branch (``csv_df`` / ``csv_path`` is None): rotate the
           ORIGINAL mask → ``<labels>.bak`` via ``shutil.copy2`` (COPY, not
           rename — original stays put so a promote failure leaves BOTH the
           original AND the .bak as recovery points), then ``os.replace``-
           promote the staging file.
        B'. Mask + CSV branch: write the CSV via ``save_patch_csv`` (the
           injected ``qc_features.save_patch_csv`` — kept as the real function
           so the existing CSV-failure tests that patch it still bite).  If the
           CSV write raises → delete the staging file (original untouched), NO
           .bak rotation, NO promote.
        C. Both writes OK → ``.bak``-rotate the original (copy) → ``os.replace``-
           promote the staging file.  Promote failure → delete the staging file
           (no orphan), original + .bak intact.

    Transactional invariants (tested in TestSaveCurationTransactional /
    TestMaskOnlySave / TestLowMemoryRollback / TestPromoteFailureCleanup):
      * The ORIGINAL mask is NEVER moved/overwritten until the very last
        ``os.replace`` promote — so a CSV failure or a mask-write failure
        leaves the on-disk mask exactly as it was (rollback substrate is the
        staging file, NOT an in-memory copy → no ``Path.read_bytes``).
      * ``.bak`` rotation is a COPY (``shutil.copy2``), and happens ONLY on the
        success path, right before the promote.
      * No orphaned ``.tif.saving`` staging file on ANY path (success or
        failure — cleaned up on every failure branch, consumed by the promote
        on success).
      * A ``.bak`` rotation failure is non-fatal (logged via ``warnings`` list,
        promote still proceeds with no rollback available) — matches legacy.

    This is the function BOTH the background ``_SaveCurationWorker`` and the
    synchronous orchestrator (``_save_curation`` / the tests) call — so the
    transactional assertions are validated without a live QThread (same
    approach as ``_commit_triage_persist``).

    Args:
        lifted_mask: the full-res-lifted ndarray to write, computed on the MAIN
            thread via ``_maybe_lift_for_save`` (a COPY so the worker never
            touches the live napari layer).  Must be non-None — the caller
            already verified an active labels layer/path before snapshotting.
        labels_path: on-disk TIFF path for the label volume (the promote
            target; ``.tif.saving`` staging + ``.bak`` are derived from it).
        csv_df: the QC features DataFrame to persist (a COPY at the call site),
            or None → mask-only save.
        csv_path: final CSV path, or None → mask-only save.
        save_patch_csv: the ``qc_features.save_patch_csv`` callable, injected so
            the worker doesn't import controller-package modules mid-run and so
            the existing tests that patch it still intercept the call.

    Returns:
        dict describing exactly which step (if any) failed so the main-thread
        handler reproduces every legacy ``_save_curation`` branch.  Keys:
          ``ok`` (bool): True iff the mask (and CSV, if applicable) persisted.
          ``stage`` (str): ``"mask_stage"`` | ``"csv"`` | ``"promote"`` |
            ``"done"`` — which step the outcome refers to.
          ``mask_only`` (bool): True if this was a mask-only save (no CSV).
          ``error`` (str|None): human-readable failure reason, else None.
          ``cleanup_ok`` (bool): on a promote failure, whether the staging file
            was successfully removed (drives the legacy cleanup log line).
          ``warnings`` (list[str]): non-fatal notes (e.g. ``.bak`` rotation
            failure) for the main thread to log.
          ``csv_path`` (str|None): echoed back for the success log line.
    """
    import os as _os
    import shutil as _shutil
    from pathlib import Path as _Path

    result = {
        "ok": False,
        "stage": "mask_stage",
        "mask_only": csv_df is None or csv_path is None,
        "error": None,
        "cleanup_ok": False,
        "warnings": [],
        "csv_path": str(csv_path) if csv_path is not None else None,
    }

    labels_path_obj = _Path(labels_path)
    staging_path = labels_path_obj.with_suffix(".tif.saving")
    bak_path = labels_path_obj.with_suffix(labels_path_obj.suffix + ".bak")

    # Phase A: write the new (already-lifted) mask to the staging path.  The
    # original at labels_path is NOT touched here.
    try:
        _atomic_tiff_write(str(staging_path), lifted_mask, dtype=np.uint32)
    except Exception as exc:
        result["stage"] = "mask_stage"
        result["error"] = f"mask write error: {exc}"
        # Staging write failed → _atomic_tiff_write cleans its own temp; nothing
        # to promote, CSV never written.  Original untouched.
        return result

    def _rotate_bak():
        """COPY original → .bak (non-fatal).  Returns a warning string or None."""
        if labels_path_obj.exists():
            try:
                _shutil.copy2(str(labels_path_obj), str(bak_path))
            except Exception as bak_exc:
                return (
                    f".bak rotation failed: {bak_exc}. "
                    f"Continuing with promote (no rollback available)."
                )
        return None

    # Mask-only branch.
    if result["mask_only"]:
        warn = _rotate_bak()
        if warn:
            result["warnings"].append(warn)
        try:
            from .qc_features import replace_with_retry
            replace_with_retry(str(staging_path), str(labels_path_obj))
        except Exception as exc:
            result["stage"] = "promote"
            result["error"] = f"mask promote error: {exc}"
            try:
                staging_path.unlink()
                result["cleanup_ok"] = True
            except Exception:
                pass
            return result
        result["ok"] = True
        result["stage"] = "done"
        return result

    # Phase B: write the CSV (mask + CSV branch).
    try:
        save_patch_csv(csv_df, str(csv_path))
    except Exception as exc:
        # CSV failed — delete the staging file, original untouched, no promote.
        try:
            staging_path.unlink()
        except Exception:
            pass
        result["stage"] = "csv"
        result["error"] = (
            f"CSV write error: {exc}. Mask not promoted (original unchanged)."
        )
        return result

    # Phase C: both writes succeeded — rotate to .bak (copy), then promote.
    warn = _rotate_bak()
    if warn:
        result["warnings"].append(warn)
    try:
        from .qc_features import replace_with_retry
        replace_with_retry(str(staging_path), str(labels_path_obj))
    except Exception as exc:
        cleanup_ok = False
        try:
            staging_path.unlink()
            cleanup_ok = True
        except Exception:
            pass
        result["stage"] = "promote"
        result["error"] = f"mask promote error: {exc}"
        result["cleanup_ok"] = cleanup_ok
        return result

    result["ok"] = True
    result["stage"] = "done"
    return result


def _safe_curation_debug_log(obj, msg: str) -> None:
    """Best-effort debug log for lightweight bound-method test harnesses."""
    dbg = getattr(obj, "_curation_debug_log", None)
    if callable(dbg):
        try:
            dbg(msg)
        except Exception:
            pass


# ---------------------------------------------------------------------------
# Stdout/stderr capture for backend log forwarding
# ---------------------------------------------------------------------------

class _SignalWriter(io.TextIOBase):
    """File-like object that forwards write() calls to a Qt Signal.

    Filters tqdm carriage-return noise and blank lines.  Emits clean,
    single-line messages suitable for a UI log widget.
    """

    _TQDM_PATT = re.compile(r"(\d+)%\|")  # e.g. " 45%|████"

    def __init__(self, signal: Signal, prefix: str = ""):
        super().__init__()
        self._signal = signal
        self._prefix = prefix
        self._last_tqdm_pct = -1

    def write(self, text: str) -> int:
        if not text:
            return 0
        for line in text.splitlines():
            line = line.strip()
            if not line:
                continue
            # Throttle tqdm: only emit at 10% increments
            m = self._TQDM_PATT.search(line)
            if m:
                pct = int(m.group(1))
                if pct - self._last_tqdm_pct < 10 and pct != 100:
                    continue
                self._last_tqdm_pct = pct
            self._signal.emit(f"{self._prefix}{line}")
        return len(text)

    def flush(self):
        pass


# ---------------------------------------------------------------------------
# Timing helpers
# ---------------------------------------------------------------------------

import time as _time


def _format_elapsed(seconds: float) -> str:
    """Format seconds into a human-readable elapsed string."""
    if seconds < 60:
        return f"{seconds:.0f}s"
    minutes, secs = divmod(int(seconds), 60)
    if minutes < 60:
        return f"{minutes}m {secs:02d}s"
    hours, minutes = divmod(minutes, 60)
    return f"{hours}h {minutes:02d}m"


def _format_eta(elapsed: float, progress: float) -> str:
    """Estimate remaining time from elapsed time and progress fraction (0-1)."""
    if progress <= 0 or progress >= 1:
        return ""
    remaining = elapsed * (1.0 - progress) / progress
    return f"~{_format_elapsed(remaining)} remaining"


