class _PredictionWorker(QObject):
    """Runs dense 2D prediction in a background thread."""
    progress = Signal(str, int, int)
    finished = Signal(dict)
    error = Signal(str)

    def __init__(self, predict_fn, **kwargs):
        super().__init__()
        self._predict_fn = predict_fn
        self._kwargs = kwargs

    def run(self):
        try:
            result = self._predict_fn(progress_cb=self.progress.emit, **self._kwargs)
            self.finished.emit(result)
        except Exception as exc:
            self.error.emit(str(exc))


class _ReconstructionWorker(QObject):
    """Runs 3D reconstruction in a background thread."""
    progress = Signal(str, int, int)
    finished = Signal(dict)
    error = Signal(str)

    def __init__(self, reconstruct_fn, **kwargs):
        super().__init__()
        self._reconstruct_fn = reconstruct_fn
        self._kwargs = kwargs

    def run(self):
        try:
            result = self._reconstruct_fn(progress_cb=self.progress.emit, **self._kwargs)
            self.finished.emit(result)
        except Exception as exc:
            self.error.emit(str(exc))


class _SerialPredictionWorker(QObject):
    """Sequentially predicts all unprocessed patches."""
    patch_started = Signal(str, int, int)     # name, current_index, total
    patch_completed = Signal(str, dict)       # name, result_dict (views)
    view_progress = Signal(str, str, int, int)  # patch_name, view, current, total
    all_completed = Signal()
    error = Signal(str, str)                  # name, error_msg

    def __init__(self, predict_fn, patch_configs: List[dict]):
        super().__init__()
        self._fn = predict_fn
        self._configs = patch_configs
        self._cancel_requested = False

    def request_pause(self):
        self._cancel_requested = True

    def run(self):
        total = len(self._configs)
        for i, cfg in enumerate(self._configs):
            if self._cancel_requested:
                break
            patch_name = cfg["patch_name"]
            self.patch_started.emit(patch_name, i, total)
            try:
                def _progress_cb(view, current, total_slices, _pn=patch_name):
                    self.view_progress.emit(_pn, view, current, total_slices)
                result = self._fn(progress_cb=_progress_cb, **cfg)
                self.patch_completed.emit(patch_name, result)
            except Exception as exc:
                self.error.emit(patch_name, str(exc))
        self.all_completed.emit()


class _SerialReconstructionWorker(QObject):
    """Sequentially reconstructs all predicted patches."""
    patch_started = Signal(str, int, int)
    patch_completed = Signal(str, dict)
    log_message = Signal(str)
    all_completed = Signal()
    error = Signal(str, str)

    def __init__(self, reconstruct_fn, patch_configs: List[dict]):
        super().__init__()
        self._fn = reconstruct_fn
        self._configs = patch_configs
        self._cancel_requested = False

    def request_pause(self):
        self._cancel_requested = True

    def run(self):
        total = len(self._configs)
        writer = _SignalWriter(self.log_message, prefix="[recon] ")
        for i, cfg in enumerate(self._configs):
            if self._cancel_requested:
                break
            patch_name = cfg["patch_name"]
            self.patch_started.emit(patch_name, i, total)
            try:
                with redirect_stdout(writer), redirect_stderr(writer):
                    result = self._fn(**cfg)
                self.patch_completed.emit(patch_name, result)
            except Exception as exc:
                self.error.emit(patch_name, str(exc))
        self.all_completed.emit()


class _BatchProcessWorker(QObject):
    """Sequentially predicts + reconstructs all unprocessed patches."""
    patch_started = Signal(str, int, int)     # name, current_index, total
    patch_completed = Signal(str, dict)       # name, result_dict
    all_completed = Signal()
    error = Signal(str, str)                  # name, error_msg

    def __init__(self, predict_and_reconstruct_fn, patch_configs: List[dict]):
        super().__init__()
        self._fn = predict_and_reconstruct_fn
        self._configs = patch_configs
        self._pause_requested = False

    def request_pause(self):
        self._pause_requested = True

    def run(self):
        total = len(self._configs)
        for i, cfg in enumerate(self._configs):
            if self._pause_requested:
                break
            patch_name = cfg["patch_name"]
            self.patch_started.emit(patch_name, i, total)
            try:
                result = self._fn(**cfg)
                self.patch_completed.emit(patch_name, result)
            except Exception as exc:
                self.error.emit(patch_name, str(exc))
        self.all_completed.emit()


# Canonical implementation moved to qc_features.py (pure numpy, no Qt).
# This alias preserves all existing call sites in this controller.
from .qc_features import extract_single_channel as _extract_single_channel


class _ExtractionWorker(QObject):
    """Extracts training pairs from curated 3D volumes in a background thread."""
    progress = Signal(int, int)  # (current_slice, total_slices)
    finished = Signal(dict)      # result summary dict
    error = Signal(str)          # error message
    log = Signal(str)            # log messages
    cancelled = Signal()        # emitted when cancel is acknowledged

    def __init__(self, workspace_dir, patch_names, image_dir, extraction_kwargs,
                 run_id=None):
        super().__init__()
        self._workspace_dir = workspace_dir
        self._patch_names = patch_names
        self._image_dir = image_dir
        self._extraction_kwargs = extraction_kwargs
        # Multi-run path-id (Option A): None → flat layout / default run.
        self._run_id = run_id
        self._cancel_requested = False

    def request_cancel(self):
        self._cancel_requested = True

    def run(self):
        try:
            from .training_pair_extractor import extract_from_workspace

            self.log.emit(
                f"Scanning {len(self._patch_names)} patches, "
                f"loading volumes and building slice list..."
            )

            def _checked_progress(current, total):
                if self._cancel_requested:
                    raise _CancelledError("Extraction cancelled")
                self.progress.emit(current, total)

            result = extract_from_workspace(
                self._workspace_dir,
                patch_names=self._patch_names,
                image_dir=self._image_dir,
                progress_cb=_checked_progress,
                run_id=self._run_id,
                **self._extraction_kwargs,
            )
            self.log.emit(
                f"Extraction complete: {result['spatial']} spatial + "
                f"{result['axial']} axial from {result['patches_processed']} patches"
            )
            self.finished.emit(result)
        except _CancelledError:
            self.cancelled.emit()
        except Exception as exc:
            import traceback
            self.error.emit(f"{exc}\n{traceback.format_exc()}")


class _CancelledError(Exception):
    """Raised internally when a background operation is cancelled."""
    pass


def count_pairs_on_disk(pairs_root) -> Tuple[int, int, int]:
    """``(n_lateral, n_axial, n_patches)`` -- the pairs a training run would
    read, counted from the DISK with the SAME scan as
    ``FusionReconstructionController._collect_training_pairs`` (the legacy
    flat ``spatial/`` / ``axial/`` folders and every per-patch
    ``{patch}/spatial|axial`` folder; a pair is an ``*_img.tif`` with its
    ``*_mask.tif``).  Pure: no Qt, no controller state, and one directory
    listing per folder instead of a stat per pair.  Never read from
    ``refinement/manifest.json`` (I11).  ``n_patches`` counts the per-patch
    folders that hold at least one pair (a legacy flat folder counts as
    one)."""
    root = Path(pairs_root)
    n_lat = n_ax = 0
    patches = set()

    def _count(d: Path) -> int:
        try:
            names = {e.name for e in os.scandir(d) if e.is_file()}
        except OSError:
            return 0
        return sum(
            1 for n in names
            if n.endswith("_img.tif")
            and n.replace("_img.tif", "_mask.tif") in names
        )

    if not root.is_dir():
        return 0, 0, 0
    for sub in sorted(root.iterdir()):
        if not sub.is_dir() or sub.name.startswith("."):
            continue
        if sub.name in ("spatial", "axial"):
            c = _count(sub)
            if sub.name == "spatial":
                n_lat += c
            else:
                n_ax += c
            if c:
                patches.add(root)
            continue
        c_lat = _count(sub / "spatial") if (sub / "spatial").exists() else 0
        c_ax = _count(sub / "axial") if (sub / "axial").exists() else 0
        n_lat += c_lat
        n_ax += c_ax
        if c_lat or c_ax:
            patches.add(sub)
    return n_lat, n_ax, len(patches)


class _RefinementTrainingWorker(QObject):
    """Runs Cellpose fine-tuning in a background thread."""
    epoch_update = Signal(int, int, float, object)  # epoch, n_epochs, train_loss, val_loss
    finished = Signal(dict)   # result dict with model_path, losses, etc.
    error = Signal(str)       # error message
    log = Signal(str)         # log messages
    cancelled = Signal()     # emitted when cancel is acknowledged

    def __init__(self, config_dict, train_images, train_masks,
                 val_images, val_masks, init_mode, init_path,
                 model_name, save_path,
                 *, bundle_name: str = "", bucket: str = "",
                 init_combo_text: str = "",
                 source_workspace: str = ""):
        super().__init__()
        self._cancel_requested = False
        self._config = config_dict
        self._train_images = train_images
        self._train_masks = train_masks
        self._val_images = val_images
        self._val_masks = val_masks
        self._init_mode = init_mode
        self._init_path = init_path
        self._model_name = model_name
        self._save_path = save_path
        # 2026-05-20 Phase 6: bundle_name + bucket drive the post-train
        # lift + schema 2.0 manifest write.  Optional/default-empty so
        # legacy callers (tests) still work — when bucket is empty, the
        # finalize step is skipped.
        self._bundle_name = bundle_name
        self._bucket = bucket
        self._init_combo_text = init_combo_text
        self._source_workspace = source_workspace
        #: sparse (epoch, val) pairs of the SAMPLED epochs (M11)
        self._val_series: list = []

    def request_cancel(self):
        self._cancel_requested = True

    def run(self):
        try:
            import tifffile
            from packages.epicycle_training.config import TrainingConfig
            from packages.epicycle_training.cellpose_trainer import CellposeTrainer

            self.log.emit(
                f"Loading {len(self._train_images)} training + "
                f"{len(self._val_images)} validation pairs..."
            )

            # Load images and masks from disk
            train_data = [tifffile.imread(p) for p in self._train_images]
            train_labels = [tifffile.imread(p) for p in self._train_masks]
            val_data = None
            if self._val_images:
                val_imgs = [tifffile.imread(p) for p in self._val_images]
                val_masks = [tifffile.imread(p) for p in self._val_masks]
                val_data = (val_imgs, val_masks)

            self.log.emit(f"Loaded. Starting training: {self._config['n_epochs']} epochs")

            # Build TrainingConfig
            cfg = self._config
            train_config = TrainingConfig(
                n_epochs=cfg["n_epochs"],
                learning_rate=cfg["learning_rate"],
                batch_size=cfg["batch_size"],
                weight_decay=cfg.get("weight_decay", 1e-5),
                momentum=cfg.get("momentum", 0.9),
                min_train_masks=cfg.get("min_train_masks", 0),
                normalize=cfg.get("normalize", True),
                rescale=cfg.get("rescale", True),
                SGD=cfg.get("SGD", True),
                compute_flows=cfg.get("compute_flows", True),
                channels=cfg.get("channels", [2, 1]),
                seed=cfg.get("seed"),
            )

            use_gpu = cfg.get("device", "gpu") == "gpu"
            trainer = CellposeTrainer(config=train_config, use_gpu=use_gpu)

            # Determine init mode
            pretrained_model = None
            base_model = None
            if self._init_mode == "custom":
                pretrained_model = self._init_path
            elif self._init_mode == "cellpose":
                base_model = self._init_path

            # Epoch callback → signal + cancel check
            n_val_pairs = len(self._val_images or [])

            def _on_epoch(epoch, n_epochs, train_loss, val_loss):
                if self._cancel_requested:
                    raise _CancelledError("Training cancelled")
                # Cellpose validates at epoch 5 and every 10th epoch, and
                # reports 0.0 elsewhere and when there is no validation set
                # (M11): only a sampled epoch of a run WITH a validation
                # set is a validation point.
                if (n_val_pairs > 0 and val_loss is not None
                        and _MRT.is_val_sampled_epoch(epoch)):
                    self._val_series.append((int(epoch), float(val_loss)))
                self.epoch_update.emit(epoch, n_epochs, train_loss, val_loss)

            trainer.fit(
                train_data=train_data,
                train_labels=train_labels,
                val_data=val_data,
                pretrained_model=pretrained_model,
                base_model=base_model,
                model_name=self._model_name,
                save_path=self._save_path,
                epoch_callback=_on_epoch,
            )

            # 2026-05-20 Phase 6: post-train lift + schema 2.0 manifest.
            # Cellpose wrote weights to ``save_path/models/{model_name}``
            # — lift them up to ``save_path/{model_name}`` per the
            # "no fighting Cellpose" pattern.  When
            # bundle_name + bucket are set (post-restructure flow),
            # call the helper.  When not (legacy/test callers), skip
            # the finalize step.
            lift_result = None
            manifest = None
            if self._bundle_name and self._bucket:
                # 2026-05-20 audit fix: re-train detection.  If
                # user re-trains the SAME bucket on the SAME bundle,
                # the prior pass left bundle/{bucket} + companion
                # files at bundle root.  Cellpose wrote a fresh
                # bundle/models/{bucket} (overwrites itself), but
                # lift_cellpose_output refuses to overwrite an
                # existing dst → new weights would be stranded in
                # models/ while manifest points to STALE bundle/
                # weights.  Pre-emptively unlink stale dst +
                # companions so the lift can install the new
                # training output.
                from pathlib import Path as _Path
                _bundle = _Path(self._save_path)
                _src = _bundle / "models" / self._bucket
                _dst = _bundle / self._bucket
                if _src.exists() and _dst.exists():
                    self.log.emit(
                        f"[PERVIEW-CELLPOSE-IO] re-train detected on "
                        f"bucket {self._bucket!r}: removing stale "
                        f"{_dst.name} + companions before lift"
                    )
                    try:
                        _dst.unlink()
                    except OSError:
                        pass
                    for _suffix in (
                        "_train_loss.npy",
                        "_val_loss.npy",
                        "_training_config.json",
                    ):
                        _stale = _bundle / f"{self._bucket}{_suffix}"
                        if _stale.is_file():
                            try:
                                _stale.unlink()
                            except OSError:
                                pass
                try:
                    from . import _refinement_bundle as _rb
                    final = _rb.finalize_refinement_pass(
                        bundle_dir=self._save_path,
                        bundle_name=self._bundle_name,
                        bucket=self._bucket,
                        log_fn=self.log.emit,
                        init_mode=self._init_mode,
                        init_path=self._init_path or None,
                        init_combo_text=self._init_combo_text or None,
                        final_train_loss=(
                            float(trainer.train_loss[-1])
                            if trainer.train_loss is not None
                            and len(trainer.train_loss) > 0
                            else None
                        ),
                        final_val_loss=(
                            float(trainer.val_loss[-1])
                            if trainer.val_loss is not None
                            and len(trainer.val_loss) > 0
                            else None
                        ),
                        n_train_pairs=len(train_data),
                        n_val_pairs=(
                            len(val_imgs) if val_data else 0
                        ),
                        n_epochs=cfg["n_epochs"],
                        source_workspace=self._source_workspace or None,
                    )
                    lift_result = final["lift"]
                    manifest = final["manifest"]
                except Exception as _post_err:
                    # Don't let lift/manifest failure crash the
                    # training pipeline — log + continue.  The user
                    # gets a [WARN] line; the model file is still on
                    # disk at the legacy Cellpose location.
                    import traceback as _tb
                    self.log.emit(
                        f"[PERVIEW-CELLPOSE-IO] WARN finalize_refinement_pass "
                        f"raised: {_post_err}\n{_tb.format_exc()}"
                    )

            # The canonical post-lift weights path (what readers
            # should consume).  When finalize ran successfully, this
            # is bundle/{bucket}; otherwise fall back to whatever
            # Cellpose returned.
            if (
                lift_result is not None
                and lift_result.get("weights_lifted")
            ):
                canonical_model_path = str(lift_result["weights_path"])
            else:
                canonical_model_path = trainer.model_path

            result = {
                "model_path": canonical_model_path,
                "raw_cellpose_path": trainer.model_path,
                "model_name": self._model_name,
                "bundle_name": self._bundle_name,
                "bucket": self._bucket,
                "save_path": self._save_path,
                "manifest": manifest,
                "n_train": len(train_data),
                "n_val": len(val_imgs) if val_data else 0,
                "val_losses": list(self._val_series),
                "train_losses": (
                    [float(v) for v in trainer.train_loss]
                    if trainer.train_loss is not None
                    else []
                ),
                "final_train_loss": (
                    float(trainer.train_loss[-1])
                    if trainer.train_loss is not None and len(trainer.train_loss) > 0
                    else None
                ),
                "final_val_loss": (
                    float(trainer.val_loss[-1])
                    if trainer.val_loss is not None and len(trainer.val_loss) > 0
                    else None
                ),
            }
            self.log.emit(
                f"Training complete: {self._model_name} → {trainer.model_path}"
            )
            self.finished.emit(result)

        except _CancelledError:
            self.cancelled.emit()
        except Exception as exc:
            import traceback
            self.error.emit(f"{exc}\n{traceback.format_exc()}")


class _QCFeatureWorker(QObject):
    """Extracts QC features from label volumes in a background thread."""
    finished = Signal(object, str)    # (DataFrame, patch_name)
    error = Signal(str)
    csv_saved = Signal(str, str)      # (patch_name, csv_path)
    log = Signal(str)
    #: R7: (patch_name, {"zyx", "source"}, launch workspace) -- a
    #: voxel size read from the patch file, emitted BEFORE ``finished`` for
    #: the main thread to store (never in another workspace)
    spacing_found = Signal(str, object, str)

    def __init__(self, labels_path: str, patch_name: str, csv_path: str,
                 spacing=None, source_stack_path: str = "",
                 erosion_iters: int = 2, max_radius: int = 5,
                 composite_method: str = "zscore",
                 seg_channel: int = 0,
                 pca_features=None,
                 prob_path: str = "",
                 n_pcs: int = 5,
                 compute_umap: bool = False,
                 umap_min_dist: float = 0.10,
                 umap_n_neighbors: int = 15,
                 compute_tsne: bool = False,
                 tsne_perplexity: float = 30.0,
                 channel_configs: Optional[list] = None,
                 exclude_border: bool = False,
                 invert_z: bool = False,
                 metric: str = "euclidean",
                 patch_status: str = "unknown",
                 spacing_from_file: bool = False,
                 spacing_workspace: str = ""):
        super().__init__()
        # R7: read the patch file's voxel tags on this thread when
        # the patch has no voxel size of its own
        self._spacing_from_file = bool(spacing_from_file)
        self._spacing_workspace = spacing_workspace or ""
        self._labels_path = labels_path
        self._patch_name = patch_name
        self._csv_path = csv_path
        # 2026-05-20: patch_status gates persist_qc_artifacts' raw-
        # backup write so post-curation extractions don't snapshot
        # wrong-data into features_raw.csv.  Defaults to "unknown"
        # for backward-compat callers; controller dispatch passes
        # the live state_manager status.
        self._patch_status = patch_status
        self._spacing = spacing
        self._source_stack_path = source_stack_path
        self._erosion_iters = erosion_iters
        self._max_radius = max_radius
        self._composite_method = composite_method
        self._seg_channel = seg_channel
        self._pca_features = pca_features
        self._prob_path = prob_path
        # Phase A.2 (2026-05-04): n_pcs drives compute_composite_score's
        # L2 norm in PC space when method=pca.  Mirrors the dialog's
        # "PCA dimensions" setting; 5 is the historical default.
        self._n_pcs = n_pcs
        # Phase A.4 (2026-05-04): opt-in nonlinear embeddings.  When
        # the corresponding checkbox is True, the worker writes
        # UMAP_1/UMAP_2 or tSNE_1/tSNE_2 columns that ride through
        # save_patch_csv into the per-patch CSV.  umap_n_neighbors is
        # shared with Leiden's n_neighbors via the dialog.
        self._compute_umap = compute_umap
        self._umap_min_dist = umap_min_dist
        self._umap_n_neighbors = umap_n_neighbors
        self._compute_tsne = compute_tsne
        self._tsne_perplexity = tsne_perplexity
        # Phase C.1 (2026-05-04): the registry migration introduces
        # three new knobs from the QC Settings dialog.  Channel configs
        # drive per-channel intensity feature extraction; exclude_border
        # influences PCA fitting + composite score; invert_z flips
        # apical/basal interpretation in cross-section features.
        self._channel_configs = channel_configs or []
        self._exclude_border = exclude_border
        self._invert_z = invert_z
        # Phase E (2026-05-04) — distance metric for the kNN graph
        # used by Leiden clustering, UMAP, and t-SNE.  Defaults
        # 'euclidean' (matches pre-Phase-E behaviour).
        self._metric = metric

    def run(self):
        """In-process FALLBACK extraction (subprocess-spawn failure path).

        2026-06-07 (feature/step3-extract-subprocess): the canonical compute
        chain was relocated VERBATIM into
        :func:`._qc_extract_core.run_full_qc_extraction` so it can run in a
        SEPARATE PROCESS (keeping the napari UI live during the 100-270s
        GIL-bound extraction).  This worker is now only used as the
        in-process fallback when ``subprocess.Popen`` raises (env / spawn
        failure) — it calls the SAME pure function so behavior is identical,
        then re-reads the CSV so the emitted ``df`` carries the same columns
        the subprocess path would re-read from disk.

        The ``self.log.emit`` Qt signal is threaded into the pure function as
        the ``log`` callback so the diagnostic console still streams progress.
        ``df.attrs["_adjacency_list"]`` is re-attached from the summary so the
        re-extract ``adjacency_curated.csv`` path in ``_on_qc_extract_finished``
        behaves identically (the CSV does not carry ``df.attrs``).
        """
        try:
            from ._qc_extract_core import run_full_qc_extraction
            from .qc_features import load_patch_csv

            summary = run_full_qc_extraction(
                labels_path=self._labels_path,
                source_stack_path=self._source_stack_path,
                prob_path=self._prob_path,
                csv_path=self._csv_path,
                patch_name=self._patch_name,
                spacing=self._spacing,
                erosion_iters=self._erosion_iters,
                max_radius=self._max_radius,
                composite_method=self._composite_method,
                seg_channel=self._seg_channel,
                pca_features=self._pca_features,
                n_pcs=self._n_pcs,
                compute_umap=self._compute_umap,
                umap_min_dist=self._umap_min_dist,
                umap_n_neighbors=self._umap_n_neighbors,
                compute_tsne=self._compute_tsne,
                tsne_perplexity=self._tsne_perplexity,
                channel_configs=self._channel_configs,
                exclude_border=self._exclude_border,
                invert_z=self._invert_z,
                metric=self._metric,
                patch_status=self._patch_status,
                progress=None,
                log=lambda msg: self._safe_log(msg),
                spacing_from_file=self._spacing_from_file,
                spacing_workspace=self._spacing_workspace,
            )
            # Re-read from the just-written CSV so the df handed to the
            # controller matches the subprocess path's re-read exactly.
            df = load_patch_csv(self._csv_path)
            df.attrs["_adjacency_list"] = list(
                summary.get("adjacency_list") or []
            )
            if summary.get("spacing_found"):
                self.spacing_found.emit(self._patch_name,
                                        summary["spacing_found"],
                                        self._spacing_workspace)
            self.csv_saved.emit(self._patch_name, self._csv_path)
            self.finished.emit(df, self._patch_name)
        except Exception as exc:
            import traceback
            _err_msg = (
                f"[QC-EXTRACT] Worker ERROR patch={self._patch_name!r} "
                f"exc={exc!r}"
            )
            print(_err_msg)
            # log.emit also so it appears in the diagnostic console.
            # Followed by the full error signal which the controller
            # routes to its own error handling.
            self._safe_log(_err_msg)
            self.error.emit(f"{exc}\n{traceback.format_exc()}")

    def _safe_log(self, msg: str) -> None:
        try:
            self.log.emit(msg)
        except Exception:
            pass


def _to_jsonable(obj):
    """``json.dumps(..., default=_to_jsonable)`` coercer for numpy scalars/arrays.

    The QC-extract config dict can carry numpy scalars (e.g. a numpy-int
    ``seg_channel`` / channel index pulled from a widget or a regionprops
    table).  Vanilla ``json.dumps`` raises ``TypeError`` on those, which would
    silently route us to the in-process FREEZE fallback for a mere
    serialization quirk.  This coerces numpy scalars → Python ``int``/``float``
    and numpy arrays → ``list`` so the subprocess path stays live.
    """
    if isinstance(obj, np.integer):
        return int(obj)
    if isinstance(obj, np.floating):
        return float(obj)
    if isinstance(obj, np.bool_):
        return bool(obj)
    if isinstance(obj, np.ndarray):
        return obj.tolist()
    if isinstance(obj, (set, tuple)):
        return list(obj)
    # Last resort — let json raise its normal TypeError for genuinely
    # unserializable objects (we only want to rescue numpy scalars/arrays).
    raise TypeError(
        f"Object of type {type(obj).__name__} is not JSON serializable"
    )


class _QCSubprocessReader(QThread):
    """Drains a QC-extraction subprocess's stdout line-by-line on a QThread.

    2026-06-07 (feature/step3-extract-subprocess): the QC feature extraction
    now runs in a SEPARATE PROCESS so the GIL-bound compute can't freeze the
    napari UI.  This reader QThread does a BLOCKING ``readline()`` loop on the
    child's stdout pipe (so the UI thread is never blocked) and re-emits each
    line via ``line`` for forwarding to the diagnostic console.  When the pipe
    closes / the process exits it reads the exit code + stderr and emits
    ``done`` exactly once.  The parent controller owns the terminal routing
    (DONE → finish handler, ERROR → error handler, CANCELLED → quiet cleanup)
    in :meth:`_on_qc_proc_done` so all UI mutation stays on the main thread via
    queued signal delivery.
    """

    line = Signal(str)            # one stdout line (rstripped)
    done = Signal(int, str)       # (returncode, tail_text)

    # How many of the last stdout lines to retain as the error "tail" forwarded
    # to _on_qc_proc_done (the child's QC-EXTRACT-ERROR + traceback land here
    # now that stderr is merged into stdout).
    _TAIL_KEEP = 60

    def __init__(self, proc, parent=None):
        super().__init__(parent)
        self._proc = proc

    def run(self):  # noqa: D401 — QThread entry
        proc = self._proc
        # The parent spawns the child with stderr MERGED into stdout
        # (stderr=subprocess.STDOUT), so this single readline loop drains the
        # ONLY pipe — sklearn/UMAP/numba/scipy stderr chatter (100-270s of it)
        # can never fill an undrained stderr buffer and deadlock the child.
        # We keep a small rolling tail so the QC-EXTRACT-ERROR marker + child
        # traceback (now on stdout) are available for the terminal handler.
        from collections import deque
        tail = deque(maxlen=self._TAIL_KEEP)
        try:
            if proc.stdout is not None:
                for raw in iter(proc.stdout.readline, ""):
                    if raw == "" and proc.poll() is not None:
                        break
                    text = raw.rstrip("\r\n")
                    if text:
                        tail.append(text)
                        self.line.emit(text)
        except Exception as exc:  # noqa: BLE001 — never let the reader crash
            self.line.emit(f"[QC-EXTRACT] reader error: {exc!r}")
        # Pipe closed — wait for the process to fully exit, then signal terminal
        # exactly once with the rolling stdout tail (carries the error text).
        try:
            proc.wait()
        except Exception:
            pass
        rc = proc.returncode if proc.returncode is not None else -1
        self.done.emit(int(rc), "\n".join(tail))


class _QCFeatureBatchWorker(QObject):
    """Extracts QC features for multiple patches sequentially in a background thread."""
    patch_done = Signal(str, int)         # (patch_name, n_labels)
    all_finished = Signal(int, int)       # (n_patches, total_labels)
    error = Signal(str)
    log = Signal(str)
    #: R7: (patch_name, {"zyx", "source"}, launch workspace) --
    #: emitted before that patch's ``patch_done``
    spacing_found = Signal(str, object, str)

    def __init__(self, patch_configs: list, spacing=None,
                 erosion_iters: int = 2, max_radius: int = 5,
                 composite_method: str = "zscore",
                 pca_features=None,
                 n_pcs: int = 5,
                 compute_umap: bool = False,
                 umap_min_dist: float = 0.10,
                 umap_n_neighbors: int = 15,
                 compute_tsne: bool = False,
                 tsne_perplexity: float = 30.0,
                 channel_configs: Optional[list] = None,
                 exclude_border: bool = False,
                 invert_z: bool = False,
                 metric: str = "euclidean"):
        """patch_configs: list of dicts with keys labels_path, patch_name, csv_path.

        Each dict may also include ``source_stack_path`` for intensity features.

        R7: a dict's ``spacing`` (its patch's voxel size, or ``None``
        = voxel units) wins over the batch-wide *spacing*; with
        ``spacing_from_file`` the patch file's tags are read here first and
        the result is emitted on ``spacing_found``.
        """
        super().__init__()
        self._configs = patch_configs
        self._spacing = spacing
        self._erosion_iters = erosion_iters
        self._max_radius = max_radius
        self._composite_method = composite_method
        self._pca_features = pca_features
        # Phase A.2 — see _QCFeatureWorker.__init__ docstring.
        self._n_pcs = n_pcs
        # Phase A.4 — see _QCFeatureWorker.__init__ docstring.
        self._compute_umap = compute_umap
        self._umap_min_dist = umap_min_dist
        self._umap_n_neighbors = umap_n_neighbors
        self._compute_tsne = compute_tsne
        self._tsne_perplexity = tsne_perplexity
        # Phase C.1 — see _QCFeatureWorker.__init__ docstring.
        self._channel_configs = channel_configs or []
        self._exclude_border = exclude_border
        self._invert_z = invert_z
        # Phase E (2026-05-04) — distance metric for the kNN graph
        # used by Leiden clustering, UMAP, and t-SNE.  Defaults
        # 'euclidean' (matches pre-Phase-E behaviour).
        self._metric = metric

    def run(self):
        """Phase C.1 (2026-05-04): batch registry-driven extraction.

        See :meth:`_QCFeatureWorker.run` for the migration rationale.
        Same per-patch flow as the single worker, looped over
        ``self._configs``.
        """
        try:
            import traceback
            import tifffile
            from .qc_features import (
                compute_composite_score,
                save_patch_csv,
                persist_qc_artifacts,
            )
            from napari_epicycle.segmentation.feature_registry import (
                build_registry, run_extraction,
            )

            total_labels = 0
            for cfg in self._configs:
                patch_name = cfg["patch_name"]
                try:
                    self.log.emit(f"[{patch_name}] Loading labels...")
                    labels = tifffile.imread(cfg["labels_path"])
                    n_labels = len(np.unique(labels)) - 1
                    self.log.emit(
                        f"[{patch_name}] {labels.shape[0]}x{labels.shape[1]}x{labels.shape[2]}, "
                        f"{n_labels} labels"
                    )

                    # Build registry inputs (same shape as
                    # _QCFeatureWorker.run — see that method's
                    # docstring for the migration rationale).
                    available: dict = {
                        "labels": labels,
                        "erosion_iters": self._erosion_iters,
                        "max_radius": self._max_radius,
                        "seg_channel": cfg.get("seg_channel", 0),
                    }
                    # R7: the patch's own voxel size (one per entry)
                    p_spacing = (cfg.get("spacing") if "spacing" in cfg
                                 else self._spacing)
                    if cfg.get("spacing_from_file"):
                        from ._qc_extract_core import (
                            resolve_patch_spacing_from_file,
                        )
                        found = resolve_patch_spacing_from_file(
                            cfg.get("source_stack_path", ""),
                            cfg.get("spacing_workspace", ""))
                        if found is not None:
                            p_spacing = list(found["zyx"])
                            self.spacing_found.emit(
                                patch_name, found,
                                str(cfg.get("spacing_workspace", "") or ""))
                    if p_spacing is not None:
                        available["spacing"] = p_spacing
                    if self._exclude_border:
                        available["exclude_border"] = True
                    if self._invert_z:
                        available["invert_z"] = True

                    src_path = cfg.get("source_stack_path", "")
                    if src_path and Path(src_path).exists():
                        if self._channel_configs:
                            self.log.emit(
                                f"[{patch_name}] Loading source stack..."
                            )
                            available["raw_stack"] = tifffile.imread(src_path)
                        else:
                            self.log.emit(
                                f"[{patch_name}] [info] No channels — "
                                "skipping intensity"
                            )

                    prob_path = cfg.get("prob_path", "")
                    if prob_path and Path(prob_path).exists():
                        self.log.emit(
                            f"[{patch_name}] Loading probability volume..."
                        )
                        available["prob_volume"] = np.load(prob_path)

                    registry = build_registry(
                        checked_channels=self._channel_configs or None,
                    )
                    registry = [g for g in registry if g.name != "composite"]

                    self.log.emit(
                        f"[{patch_name}] Extracting "
                        f"({len(registry)} feature groups)..."
                    )
                    df = run_extraction(
                        registry, available,
                        progress_cb=lambda pct: None,
                    )

                    available.pop("prob_volume", None)
                    available.pop("raw_stack", None)

                    # Phase E — canonical PCA persistence.  See
                    # _QCFeatureWorker.run() for the rationale.
                    from .qc_features import compute_pca_columns
                    self.log.emit(
                        f"[{patch_name}] PCA "
                        f"(n_components={self._n_pcs})..."
                    )
                    compute_pca_columns(
                        df,
                        n_components=self._n_pcs,
                        features=self._pca_features,
                        exclude_border=self._exclude_border,
                    )

                    self.log.emit(
                        f"[{patch_name}] Composite score "
                        f"({self._composite_method})..."
                    )
                    compute_composite_score(
                        df,
                        method=self._composite_method,
                        features=self._pca_features,
                        exclude_border=self._exclude_border,
                        n_pcs=self._n_pcs,
                    )

                    # Phase A.4 — opt-in nonlinear embeddings, see
                    # _QCFeatureWorker.run() comment for shared pca_dims
                    # rationale.
                    if self._compute_umap:
                        self.log.emit(
                            f"[{patch_name}] UMAP "
                            f"(n_neighbors={self._umap_n_neighbors}, "
                            f"min_dist={self._umap_min_dist})..."
                        )
                        from .qc_features import compute_umap_embedding
                        compute_umap_embedding(
                            df,
                            n_neighbors=self._umap_n_neighbors,
                            min_dist=self._umap_min_dist,
                            features=self._pca_features,
                            pca_dims=self._n_pcs,
                            metric=self._metric,
                        )
                    if self._compute_tsne:
                        self.log.emit(
                            f"[{patch_name}] t-SNE "
                            f"(perplexity={self._tsne_perplexity})..."
                        )
                        from .qc_features import compute_tsne_embedding
                        compute_tsne_embedding(
                            df,
                            perplexity=self._tsne_perplexity,
                            features=self._pca_features,
                            pca_dims=self._n_pcs,
                            metric=self._metric,
                        )

                    save_patch_csv(df, cfg["csv_path"])
                    # 2026-05-20 Step 3 restructure: persist
                    # features_raw + adjacency CSVs.  See
                    # _QCFeatureWorker for full rationale.  Per-patch
                    # status (from cfg) gates the raw-backup write.
                    try:
                        artifacts = persist_qc_artifacts(
                            df, cfg["csv_path"],
                            patch_status=cfg.get("patch_status", "unknown"),
                        )
                        if artifacts["raw_backup_written"]:
                            self.log.emit(
                                f"[{patch_name}] Wrote features_raw.csv "
                                f"backup (initial extraction)"
                            )
                        if artifacts["raw_skipped_post_curation"]:
                            self.log.emit(
                                f"[{patch_name}] [NOTE] Skipped "
                                f"features_raw.csv — first extraction "
                                f"occurred POST-curation."
                            )
                        if artifacts["adjacency_written"]:
                            kind = "raw" if artifacts["is_pre_curation"] else "curated"
                            self.log.emit(
                                f"[{patch_name}] Wrote adjacency_{kind}.csv"
                            )
                    except Exception as _persist_err:
                        self.log.emit(
                            f"[{patch_name}] [WARN] QC artifact "
                            f"persistence raised: {_persist_err}"
                        )
                    total_labels += len(df)
                    self.log.emit(f"[{patch_name}] Done — {len(df)} labels")
                    self.patch_done.emit(patch_name, len(df))
                except Exception as exc:
                    tb = traceback.format_exc()
                    self.log.emit(f"[{patch_name}] ERROR: {exc}")
                    self.log.emit(tb)
                    self.error.emit(f"{patch_name}: {exc}")
                    return

            self.all_finished.emit(len(self._configs), total_labels)
        except Exception as exc:
            import traceback
            self.error.emit(f"{exc}\n{traceback.format_exc()}")


class _PatchLoadWorker(QObject):
    """Reads + downsamples a patch's labels (+ optional source stack) off the
    main thread for the Step 3 QC-view patch switch.

    The CPU-heavy work (TIFF read ~0.6s, label majority-downsample ~2s, source
    transpose-to-channel-first + downsample ~4-5s) runs here; only the cheap
    GPU layer-adds + metadata write + downstream UI refresh stay on the main
    thread (see ``_on_patch_loaded``).

    ``to_channel_first`` is the controller's pure ``_to_channel_first`` bound
    method — verified to be self-state-free and Qt-free (it calls
    ``detect_axes_order`` + ``np.moveaxis`` only), so it is safe to invoke from
    this worker thread.
    """
    loaded = Signal(object)   # dict: labels, source, downsample_factor, original_labels_shape
    error = Signal(str)
    progress = Signal(str)  # stage text — streamed into the busy status label

    def __init__(self, labels_path, source_path, need_source,
                 downsample_factor, to_channel_first):
        super().__init__()
        self._labels_path = labels_path
        self._source_path = source_path
        self._need_source = need_source
        self._downsample_factor = downsample_factor
        self._to_channel_first = to_channel_first

    def run(self):
        try:
            import tifffile
            import traceback  # noqa: F401  (referenced in except below)
            from napari_epicycle.fusion_reconstruction.downsample import (
                downsample_labels_majority, downsample_image,
            )
            # Stage 1: read TIFF(s) off-thread.
            self.progress.emit("reading…")
            labels = tifffile.imread(self._labels_path)
            original_labels_shape = labels.shape
            source = (
                tifffile.imread(self._source_path)
                if self._need_source else None
            )
            # Stage 2: majority-downsample labels (the ~2s phase) — only emit
            # this stage when downsample is actually on (otherwise it's a no-op).
            if self._downsample_factor > 1:
                self.progress.emit("downsampling…")
                labels = downsample_labels_majority(
                    labels, self._downsample_factor
                )
            # Stage 3: transpose + downsample the source stack (the ~4-5s phase).
            if source is not None:
                self.progress.emit("processing channels…")
                source = self._to_channel_first(source)
                if self._downsample_factor > 1:
                    source = downsample_image(source, self._downsample_factor)
            # Stage 4: hand back to the main thread for GPU layer adds.
            self.progress.emit("rendering…")
            self.loaded.emit({
                "labels": labels,
                "source": source,
                "downsample_factor": self._downsample_factor,
                "original_labels_shape": original_labels_shape,
            })
        except Exception as exc:
            import traceback
            self.error.emit(f"{exc}\n{traceback.format_exc()}")


class _AsyncComputeWorker(QObject):
    """Generic off-thread compute worker for the EDA recompute ops
    (PCA / UMAP / t-SNE / clustering).

    Runs an arbitrary ``compute_fn`` (a PURE closure captured on the main
    thread that operates on a DataFrame COPY of the active subset — never on
    shared controller state) on a background ``QThread`` so the busy bar's
    marquee keeps animating.  Emits ``done(result)`` on success or
    ``error(msg)`` on failure.  The main-thread ``done`` handler does ALL
    writes back to ``self._qc_features_df`` + plot refresh; the worker thread
    NEVER touches shared state.
    """
    done = Signal(object)   # result payload (whatever compute_fn returns)
    error = Signal(str)

    def __init__(self, compute_fn):
        super().__init__()
        self._fn = compute_fn

    def run(self):
        try:
            self.done.emit(self._fn())
        except Exception as exc:
            import traceback
            self.error.emit(f"{exc}\n{traceback.format_exc()}")


class _CommitTriageWorker(QObject):
    """Runs the Commit-Triage transactional persist off the main thread.

    The slow steps — full-res TIFF write (``_atomic_tiff_write``) + the
    ``df.to_csv`` stage — are numpy + tifffile I/O which RELEASE the GIL, so a
    plain ``QThread`` frees the main loop (the busy-bar marquee animates + the
    viewer stays pannable) without needing a subprocess.

    The worker calls the PURE ``_commit_triage_persist`` (no Qt, no controller
    state) on a payload captured entirely on the main thread: the mask is a
    full-res-lifted numpy COPY (the worker NEVER touches the live napari
    layer), and the df is the already-mutated COPY.  It emits ``finished(dict)``
    with the persist result, or ``error(str)`` on an unexpected exception.  All
    in-memory state writes + UI refresh happen in the main-thread handlers.
    """
    finished = Signal(object)   # result dict from _commit_triage_persist
    error = Signal(str)

    def __init__(self, persist_kwargs):
        super().__init__()
        self._kwargs = persist_kwargs

    def run(self):
        try:
            result = _commit_triage_persist(**self._kwargs)
            self.finished.emit(result)
        except Exception as exc:
            import traceback
            self.error.emit(f"{exc}\n{traceback.format_exc()}")


class _SaveCurationWorker(QObject):
    """Runs the Save-Curation transactional persist off the main thread.

    Parallel to ``_CommitTriageWorker`` (the two are near-identical "call a
    pure fn, emit finished/error" shells; kept separate so each hardcodes its
    own pure persist — and so async Save never touches the audited commit-triage
    code).  The slow step is the full-res TIFF stage write (``_atomic_tiff_write``
    via ``_save_curation_persist``) which is tifffile I/O that RELEASES the GIL,
    so a plain ``QThread`` frees the main loop (busy-bar marquee animates + the
    viewer stays pannable) without a subprocess.

    The worker calls the PURE ``_save_curation_persist`` (no Qt, no controller
    state) on a payload captured entirely on the main thread: the mask is a
    full-res-lifted numpy COPY (the worker NEVER touches the live napari layer)
    and the df is a COPY.  It emits ``finished(dict)`` with the persist result,
    or ``error(str)`` on an unexpected exception.  All in-memory state writes +
    UI refresh happen in the main-thread handlers.
    """
    finished = Signal(object)   # result dict from _save_curation_persist
    error = Signal(str)

    def __init__(self, persist_kwargs):
        super().__init__()
        self._kwargs = persist_kwargs

    def run(self):
        try:
            result = _save_curation_persist(**self._kwargs)
            self.finished.emit(result)
        except Exception as exc:
            import traceback
            self.error.emit(f"{exc}\n{traceback.format_exc()}")


