# Helpers
# ---------------------------------------------------------------------------

@contextmanager
def _block_signals(widget):
    """Temporarily block Qt signals on *widget*."""
    widget.blockSignals(True)
    try:
        yield
    finally:
        widget.blockSignals(False)


# ---------------------------------------------------------------------------
# Controller
# ---------------------------------------------------------------------------

class _Step3ThumbBatch:
    """One batch of patch pictures (V2): its token, and the two
    BOUND slots handed to the shared worker (never lambdas: a slot held only by
    PyQt can lose its closure when napari garbage-collects during a layer
    removal; the worker keeps a reference to each).  A picture
    reaches the controller with the token of the batch that drew it, so one
    from an older batch is dropped there.  ``done`` turns True when the
    worker has finished: every picture it drew has been delivered by then
    (its signals are queued in order), so a batch that is done and still
    owes a picture lost it (a worker error) and is started again."""

    # PyQt holds a connected bound method of a plain object through a WEAK
    # reference to it, so the object must be weak-referenceable; the worker
    # keeps each slot (``_on_ready`` ...) and the controller the batch.
    __slots__ = ("ctrl", "token", "done", "__weakref__")

    def __init__(self, ctrl, token: int):
        self.ctrl = ctrl
        self.token = int(token)
        self.done = False

    def finished(self):
        self.done = True

    def ready(self, name, patch_path, png_path, png_bytes):
        self.ctrl._on_thumb_ready(self.token, name, patch_path, png_path,
                                  png_bytes)

    def failed(self, name, patch_path, reason):
        self.ctrl._on_thumb_failed(self.token, name, patch_path, reason)


def _prov_window_alive(dlg, *, visible: bool = True) -> bool:
    """A model details window not yet deleted (and, with *visible*, still
    on screen -- a closed one is going away)."""
    try:
        from qtpy import sip as _sip
        if _sip.isdeleted(dlg):
            return False
    except Exception:      # noqa: BLE001 -- no sip: ask Qt
        pass
    try:
        return bool(dlg.isVisible()) if visible else True
    except RuntimeError:
        return False


class _ProvenanceNotesSaver:
    """The details window's ``on_save``: a plain object whose BOUND method
    the window keeps (never a lambda), remembering the patch and the
    workspace / run it was opened in (R6)."""

    def __init__(self, controller, patch_name: str):
        self._controller = controller
        self.patch_name = patch_name
        self.workspace = getattr(controller, "working_dir", "") or ""
        self.run_id = _active_run_path_id(controller)

    def save(self, notes: str):
        return self._controller._save_provenance_notes(
            self.patch_name, notes, self.workspace, self.run_id)


class FusionReconstructionController:
    def __init__(
        self,
        widget,
        viewer,
        *,
        reconstruction_service: Optional[ReconstructionPipelineService] = None,
        run_store: Optional[ReconstructionRunStore] = None,
    ):
        self.ui = widget
        self.viewer = viewer
        self.working_dir = ""
        self.loaded_stack_dir = ""
        #: True while `loaded_stack_dir` came from the Step 1 default rather
        #: than from Browse / persisted state (B3).  Never persisted.
        self._stack_dir_is_default = False
        self.reconstruction_service = reconstruction_service or ReconstructionPipelineService()
        self.run_store = run_store or ReconstructionRunStore()

        # Per-patch workflow state
        self.state_manager = ReconstructionStateManager()
        # S1 (audit L4): the voxel-size file is keyed by path, so a write
        # with no patch folder known is refused rather than keyed by a name
        self.state_manager.require_stack_dir = True

        # Cached predictions — predict once, reconstruct many times
        #: the patch whose prediction cache was last seen on disk by a
        #: Session click (an existence check -- no array is read; A2)
        self._cached_source_path: str = ""

        # Model source mode
        self._model_source_mode: str = "auto"

        # Thread references (prevent GC)
        self._prediction_thread: Optional[QThread] = None
        self._prediction_worker: Optional[_PredictionWorker] = None
        self._serial_prediction_thread: Optional[QThread] = None
        self._serial_prediction_worker: Optional[_SerialPredictionWorker] = None
        self._reconstruction_thread: Optional[QThread] = None
        self._reconstruction_worker: Optional[_ReconstructionWorker] = None
        self._serial_reconstruction_thread: Optional[QThread] = None
        self._serial_reconstruction_worker: Optional[_SerialReconstructionWorker] = None
        self._batch_thread: Optional[QThread] = None
        self._batch_worker: Optional[_BatchProcessWorker] = None
        # EDA recompute worker (PCA / UMAP / tSNE / clustering), 2026-06-06.
        self._compute_thread: Optional[QThread] = None
        self._compute_worker: Optional["_AsyncComputeWorker"] = None
        # Commit-Triage async persist worker (2026-06-07).  The transactional
        # CSV/TIFF write (full-res lift + atomic TIFF + to_csv) runs off the
        # main thread so the UI stays responsive + the busy marquee animates.
        self._commit_triage_thread: Optional[QThread] = None
        self._commit_triage_worker: Optional["_CommitTriageWorker"] = None
        # Save-Curation async persist worker (2026-06-07).  The transactional
        # stage→.bak→promote TIFF write (full-res lift + atomic staging write +
        # CSV) runs off the main thread (Save button path) so the UI stays
        # responsive + the busy marquee animates.  Mirrors the commit-triage
        # plumbing; gated by _save_in_flight (reused as the async run flag).
        self._save_curation_thread: Optional[QThread] = None
        self._save_curation_worker: Optional["_SaveCurationWorker"] = None
        self._shutdown_done: bool = False

        # QC state
        self._qc_features_df = None  # current patch features DataFrame
        # 2026-05-31 (fix/qc-stale-notice): tracks whether the spacing or
        # downsample factor has drifted from what was active at QC feature
        # extraction time.  Set by _check_qc_extraction_staleness() on patch
        # load + after QC settings dialog accept.  None = match (or no
        # sidecar — backward-compat); str = short reason for the staleness.
        # Used to gate the one-time modal notification.
        self._qc_extraction_stale: Optional[str] = None
        # Tracks whether we've already shown the staleness modal for this
        # patch in this session.  Prevents re-showing the dialog on every
        # patch reload or QC settings touch.  Cleared on successful
        # re-extract.  Keyed by (patch_name, reason_signature) so a new
        # kind of drift on the same patch re-prompts.
        self._qc_staleness_notified: set = set()
        # ── QC-extract subprocess state (2026-06-07, step3-extract-subprocess) ──
        # The QC feature extraction now runs in a SEPARATE PROCESS so the
        # GIL-bound compute can't freeze the napari UI.  These track the live
        # subprocess + its stdout-reader QThread + the temp config path (for
        # cleanup + the cancel-file sentinel) + the context needed by the
        # terminal handler (patch_name / csv_path).  Cleared at every
        # termination path (done / error / cancel / fallback).
        self._qc_proc = None              # subprocess.Popen | None
        self._qc_proc_reader = None       # _QCSubprocessReader | None
        self._qc_proc_config_path = None  # str | None — temp config JSON
        self._qc_proc_patch_name = ""     # patch the live proc is extracting
        self._qc_proc_workspace = ""      # the workspace it was launched in
        self._qc_proc_csv_path = ""       # CSV the live proc writes
        self._qc_proc_cancelled = False   # set when we asked the proc to cancel
        # 2026-06-07: True while the QC-extract subprocess is live.  Lets
        # _refresh_step3_lock special-case extract_features_btn so it stays
        # ENABLED as "Cancel Extraction" during its OWN run (mirrors
        # extract_training_pairs_btn + launch_refinement_btn).  Cleared on every
        # subprocess termination path (done / error / cancel).
        self._qc_extract_running = False
        # Switch-safety (B hole 1): True while the "Extract All"
        # batch worker (_QCFeatureBatchWorker) runs across all reconstructed
        # patches.  Unlike the single-patch extract (which locks via
        # _busy_show → _curation_busy), Extract All set NO lock flag — so a
        # patch switch mid-batch was an unguarded cross-patch race (its
        # per-patch set_patch_status would land in the wrong patch context).
        # OR'd into _refresh_step3_lock + the patch-switch guard; set at
        # launch, cleared on every batch-termination path.
        self._extract_all_running = False
        # Per-patch tier-line memory (Phase 2C+, 2026-05-04).  Maps
        # patch_name -> (t1, t2, t3) — the user's last-dragged tier
        # thresholds for that patch.  In-memory only; cleared on
        # session restart.  Used to persist drag positions across
        # patch switches without forcing the user to Commit Triage.
        # Committed work (qc_tier column saved to disk) is the
        # cross-session persistence layer.
        self._patch_tier_thresholds: Dict[str, tuple] = {}
        # Keyed by (label_id,) — population mode removed 2026-05-03.
        self._flagged_centroids: Dict[tuple, Tuple[int, int, int]] = {}
        # _grid_layers removed 2026-05-03 (drop-population-mode Commit 3/6).
        self._qc_view_layers: list = []  # napari layers for single-patch QC view
        self._qc_view_patch_name: str = ""  # currently loaded QC patch name
        self._manifest_cache: Dict[str, dict] = {}  # run_id → manifest payload cache
        #: V1 (row 27): listed patches whose file is gone; recomputed on the
        #: folder load, a run switch and step enter, never per list rebuild
        self._missing_patches: set = set()
        self._isolated_label_ids: set = set()  # currently lasso-isolated labels
        self._isolated_df_indices: list = []   # DataFrame row indices for isolation

        # Colormap ownership protocol (WP-0/WP-2)
        from .colormap_authority import ColormapAuthority
        self._colormap_authority = ColormapAuthority()
        # The one colour path: real
        # viewer recolours so far, and per labels layer the colormap object
        # it holds after our last write + the digest of what we wrote.
        import weakref as _weakref
        self._viewer_recolours: int = 0
        self._last_qc_colormap = _weakref.WeakKeyDictionary()
        # True while a load chain holds the one path (P3 audit 4).
        self._colours_held: bool = False
        self._tier_undo_stack: list = []  # undo stack for tier assignments (max 10)

        # Curation commit state
        from packages.epicycle_annotator.curation_undo import CurationUndoStack
        self._curation_undo_stack = CurationUndoStack(max_depth=20)
        self._curation_dirty: bool = False  # True when in-memory edits diverge from disk
        self._tiers_dirty: bool = False  # True when tier assignments diverge from disk CSV
        self._committing_triage: bool = False  # Guard: suppress dirty-marking during commit refresh
        self._edited_patches: set = set()  # patches with curation edits (for ✎ badge)
        self._llm_removal_cb_installed: bool = False  # Guard for one-time callback setup

        # ── Persistence safety (added 2026-05-03; reused as the async
        #    in-flight flag 2026-06-07) ──
        # Tracks an in-flight save so patch-switch / reset / finalize can
        # block until disk persistence settles.  Without this guard, fast
        # context switches during save can trigger races where stale UI
        # state writes to the wrong patch path.  Set by the async launcher
        # (_save_curation_async) for the duration of the background QThread,
        # and by the synchronous orchestrator (_save_curation) for the brief
        # duration of its on-thread write; cleared on every terminal path.
        # OR'd into _refresh_step3_lock + the patch-switch guard.
        self._save_in_flight: bool = False
        # The patch_name CAPTURED at save dispatch.  Used to verify that
        # a save's target hasn't drifted relative to UI state during the
        # save window — e.g. user clicks Save then switches patches before
        # save completes.  Set by _save_curation, cleared after.
        self._save_dispatch_patch: str | None = None
        # 2026-06-07: async Save-Curation run token + dispatch patch (mirror
        # _commit_triage_token / _commit_triage_dispatch_patch).  A monotonic
        # token bumped on every async launch lets a stale finish — after a
        # patch switch that somehow slipped the lock, or a shutdown — discard
        # its in-memory dirty-flag/state update.  The dispatch patch is the
        # patch the async save targeted (the lock already blocks switches, so
        # this is a backstop).
        self._save_curation_token: int = 0
        self._save_curation_dispatch_patch: str = ""

        # U0/U1: Selection sync coordinator
        from .curation_selection_sync import CurationSelectionSyncCoordinator
        self._selection_sync = CurationSelectionSyncCoordinator(
            apply_viewer_isolation=self._apply_viewer_isolation_adapter,
            apply_viewer_navigation=self._apply_viewer_navigation_adapter,
            apply_plot_highlight=self._apply_plot_highlight_adapter,
            apply_flagged_list_selection=self._apply_flagged_list_adapter,
            apply_navigator_selection=None,  # set when annotator opens
        )
        self._selection_sync.set_rejection_callback(
            self._on_selection_rejected
        )
        self._init_selection_sync_trace()

        from .qc_features import PCA_FEATURES
        self._qc_settings: dict = {
            "spacing": None,
            "spacing_values": (1.0, 1.0, 1.0),
            "erosion_iters": 2,
            "max_radius": 5,
            "composite_method": "zscore",
            "cluster_algorithm": "leiden",
            "min_cluster_size": 15,
            "n_clusters": 5,
            "leiden_resolution": 1.0,
            "leiden_n_neighbors": 15,
            "n_cluster_components": 5,
            "pca_features": list(PCA_FEATURES),
        }

        # Pipeline mutex state
        self._predicting_patches: set = set()
        self._reconstructing_patches: set = set()
        self._prediction_running: bool = False
        self._reconstruction_running: bool = False
        # Model-refinement TRAINING run flag (2026-06-06 — wire training into
        # the unified Step-3 busy lock).  Set True the moment training COMMITS
        # to launching a thread (Cancel enables in
        # _launch_next_refinement) and cleared at the single training-fully-done
        # funnel (_restore_launch_button) so it spans BOTH orientations of a
        # "Both" run (lateral→axial — the queue stays non-empty between them, so
        # _restore_launch_button is NOT called until the LAST orientation ends).
        self._refinement_running: bool = False
        # Training-pair EXTRACTION run flag (2026-06-06 FIX-2 — wire extraction
        # into the unified Step-3 busy lock).  Extraction is a long QThread op
        # that previously self-managed only its own button + manually disabled
        # launch_refinement_btn — it did NOT route through _refresh_step3_lock,
        # so the curate surface / predict / reconstruct / step-nav stayed
        # UNLOCKED during it, and any curate op's _busy_hide → _refresh_step3_lock
        # would re-enable launch_refinement_btn mid-extraction (re-enable hole).
        # Set True at extraction launch (button flips to "Cancel Extraction"),
        # cleared at the single _restore_extract_button funnel (and defensively
        # in _cleanup_extraction_thread + the launch-failure guard).  After every
        # set/clear → _refresh_step3_lock so the nav lock never strands.
        self._extraction_running: bool = False
        # Curate-surface busy flags (hygiene init; otherwise only set on first
        # use + read via getattr).  Ensures they always exist so the unified
        # Step 3 lock predicates + the predict/reconstruct entry guards never
        # depend on attribute-creation order.
        self._curation_busy: bool = False
        self._patch_load_in_flight: bool = False
        # Batch-Refine run flag (2026-06-07).  Set True by the annotator (via
        # the injected _on_annotator_batch_refine_lock callback) at the moment a
        # Batch Refine STARTS, and held until the op is FULLY resolved
        # (accept / reject / worker error / cancel / dialog close) — covering
        # BOTH the worker compute AND the staged-preview window (the volume is
        # not final until accept/reject).  OR'd into _refresh_step3_lock so the
        # whole Step-3 surface (predict / reconstruct / extract / commit / save /
        # step-nav / patch-switch + the annotator drawing + navigator action
        # buttons via set_load_locked) locks for the duration.  Lives on the
        # CONTROLLER (the annotator drives it through the callback) so a
        # standalone annotator with no controller simply has no callback wired.
        self._batch_refine_running: bool = False
        # De-novo "Add" mode run flag (2026-06-30).  True while the annotator's
        # Add tool holds the surface (box placed → threshold → preview →
        # accept/reject).  Driven by the annotator through on_add_mode_lock,
        # OR'd into _refresh_step3_lock + the patch-switch guard exactly like
        # _batch_refine_running.
        self._add_mode_running: bool = False
        # Reshape (guided Split / Add) run flag (2026-09-08, Brick R1).
        # True
        # from the moment the guided mode STARTS until it is FULLY resolved
        # (accept / reject / cancel / error / patch-switch teardown).  Driven by
        # the annotator through on_reshape_lock, OR'd into _refresh_step3_lock +
        # the patch-switch guard exactly like _add_mode_running.
        #
        # DELIBERATE BEHAVIOUR CHANGE (grill A6): the MANUAL
        # split has NO controller-level lock today (_split_running is a
        # widget-local flag and never reaches _refresh_step3_lock's OR), so
        # while a manual split is staged with the target punched out of the
        # volume, Save Curation and Commit Triage are both enabled and will
        # happily persist a volume with a HOLE in it.  The guided path takes
        # this lock BEFORE the hole punch and holds it until the target is
        # restored or the result is written, so Save/Commit cannot persist a
        # half-finished volume.  Extending the same lock to the manual split is
        # a separate, grilled change (follow-up F2).
        self._reshape_running: bool = False
        # 2026-09-22 (Brick B1): the Refine tab's twin.  Raised while a
        # RefineWorker is in flight OR a refine result is staged -- a
        # staged preview is already written into the shared volume, so
        # Save Curation, Commit Triage and a run switch must all be
        # unavailable for the whole staged window (REFINE).
        self._refine_running: bool = False
        # Commit-Triage async persist run flag (2026-06-07).  True from the
        # moment _commit_triage launches the worker until its finish/error
        # handler runs.  OR'd into _refresh_step3_lock (alongside
        # _extraction_running etc.) so the commit locks the curate surface +
        # step-nav + blocks patch-switch for the duration.  A monotonic token
        # (mirrors _patch_load_token) lets a stale finish — after a patch
        # switch slipped through — discard its in-memory state update.
        self._commit_triage_in_flight: bool = False
        self._commit_triage_token: int = 0
        self._commit_triage_dispatch_patch: str = ""

        # Switch-safety (B hole 2): stale-finish guard for the async
        # EDA/auto-cluster compute (_AsyncComputeWorker — cluster / PCA / UMAP /
        # tSNE).  The compute is gated by _curation_busy (which blocks a
        # patch-switch), but it had NO stale-finish guard: if the active patch
        # changes between launch and finish (a future run-switch, or any path
        # that mutates _qc_view_patch_name without the busy guard), the apply
        # closure would write the OLD df back into the NEW patch's in-memory df
        # AND its on-disk CSV (the path is re-resolved at apply-time).  A
        # monotonic token + the launch-time patch name let the finish handler
        # discard a result computed against a now-stale context.  (Mirrors the
        # _commit_triage_token / _on_qc_extract_finished patch-name guards.)
        self._compute_dispatch_token: int = 0
        self._compute_dispatch_patch: str | None = None

        # Run-switch infra (Phase 3a).  Monotonic run-epoch bumped by
        # the switch orchestrator (_switch_active_run) at the moment the run
        # context flips.  Phase 3c will have the 9 async workers CAPTURE this at
        # launch and DISCARD any finish whose epoch != the current epoch (so a
        # worker launched against the OLD run can't write its result into the
        # NEW run's in-memory df / on-disk CSV).  Here we only build the INFRA —
        # the per-worker capture+check is deferred to 3c.
        self._run_epoch: int = 0
        # Re-entry guard for the switch orchestrator (set/cleared in try/finally).
        self._run_switch_in_flight: bool = False

        # Model refinement state
        self._last_refined_model_dir: Optional[str] = None
        self._last_refinement_mode: str = ""
        self._extraction_thread: Optional[QThread] = None
        self._extraction_worker: Optional[_ExtractionWorker] = None
        self._refinement_thread: Optional[QThread] = None
        self._refinement_worker: Optional[_RefinementTrainingWorker] = None
        self._refinement_queue: List[str] = []
        self._current_refinement_mode: str = ""
        # The bundle name of the current run, chosen ONCE in
        # _launch_refinement so both passes of "Both" write one bundle.
        self._refinement_bundle_name: Optional[str] = None
        # Brick A (I4): everything the passes of one run read, taken ONCE
        # at launch; _launch_next_refinement never reads a widget.
        self._refinement_launch_snapshot: Optional[dict] = None
        # Brick A (I12): the RUN-level start time (the per-pass
        # _refinement_start_time resets at every pass).
        self._refinement_run_started: Optional[float] = None
        # The buckets ("lateral" / "axial") whose pass of the current run
        # produced a model; _current_refinement_mode is the PASS being trained.
        self._refinement_trained_buckets: set = set()
        # Brick B2: Cancel was asked (greys Cancel until the run ends); the
        # last epoch seen and the last SAMPLED validation loss of the live
        # pass; each finished pass's result (the card's source); the card
        # last shown (None = the empty sentences); the live pass's n_val.
        self._refinement_cancel_requested: bool = False
        self._refinement_last_epoch: int = 0
        self._refinement_last_val: Optional[float] = None
        self._refinement_n_val: int = 0
        self._refinement_pass_results: dict = {}
        self._refinement_last_card: Optional[dict] = None

        self._connect_signals()
        self._connect_shutdown_hooks()
        self._check_gpu_status()

    # ------------------------------------------------------------------
    # Signal wiring
    # ------------------------------------------------------------------

    def _connect_signals(self):
        ui = self.ui
        # Session
        ui.set_workdir_browse_button.clicked.connect(self._browse_workdir)
        # Run picker (Phase 4b multi-run) — getattr-guarded so a partial UI
        # (e.g. an older ui.py without the run row) never crashes wiring.
        #  * .activated (NOT .currentIndexChanged) so programmatic refreshes
        #    don't fire a switch — only a user pick does.
        _run_combo = getattr(ui, "run_picker_combo", None)
        if _run_combo is not None:
            _run_combo.activated.connect(self._on_run_combo_changed)
        _new_run_btn = getattr(ui, "new_run_button", None)
        if _new_run_btn is not None:
            _new_run_btn.clicked.connect(self._on_new_run_clicked)
        _manage_runs_btn = getattr(ui, "manage_runs_button", None)
        if _manage_runs_btn is not None:
            _manage_runs_btn.clicked.connect(self._on_manage_runs_clicked)
        ui.set_patch_directory_button.clicked.connect(self._browse_stack_dir)
        ui.loaded_patch_list.currentItemChanged.connect(self._on_patch_selected)
        # Model source
        ui.model_source_combo.currentIndexChanged.connect(self._on_model_source_changed)
        ui.pretrained_combo.currentTextChanged.connect(self._on_pretrained_changed)
        ui.lateral_model_browse.clicked.connect(self._browse_lateral_model)
        ui.axial_model_browse.clicked.connect(self._browse_axial_model)
        # Prediction + Reconstruction (unified patch state list)
        ui.predict_selected_btn.clicked.connect(self._predict_all)
        ui.reconstruct_selected_btn.clicked.connect(self._reconstruct_selected)
        ui.pipeline_cancel_btn.clicked.connect(self._cancel_pipeline)
        # R3: the foot's gates follow the highlighted patches
        ui._patch_state_list.itemSelectionChanged.connect(
            self._on_pr_selection_changed)
        # V1 (row 20): the ticks choose what runs
        ui._patch_state_list.itemChanged.connect(self._on_pr_item_changed)
        _sel_all = getattr(ui._patch_state_list, "select_all_requested", None)
        if _sel_all is not None:
            _sel_all.connect(self._on_pr_tick_every)
        _tick_link = getattr(ui, "pr_tick_all_link", None)
        if hasattr(_tick_link, "clicked"):
            _tick_link.clicked.connect(self._on_pr_tick_all_unprocessed)
        # V1 (row 27): a missing row's menu offers Forget
        ui._patch_state_list.customContextMenuRequested.connect(
            self._on_pr_list_menu)
        # V2: Session's and Curation's painted rows draw the same ⋯ on a
        # missing patch -- the same menu
        for _dname in ("_pr_row_delegate", "_curation_row_delegate"):
            _row_delegate = getattr(ui, _dname, None)
            if _row_delegate is not None:
                _row_delegate.menu_requested.connect(self._on_pr_row_menu)
        # R7: Session's ⋯ and right-click offer Set
        # spacing… (and Forget on a missing patch); the button under the
        # list acts on the highlighted rows
        _s_delegate = getattr(ui, "_session_row_delegate", None)
        if _s_delegate is not None:
            _s_delegate.menu_requested.connect(self._on_session_row_menu)
            # A2 (board B): the row's eye and its inline Set spacing…
            if hasattr(_s_delegate, "action_clicked"):
                _s_delegate.eye_clicked.connect(self._on_session_eye)
                _s_delegate.action_clicked.connect(
                    self._on_session_row_action)
        _s_list = getattr(ui, "loaded_patch_list", None)
        if _s_list is not None and hasattr(_s_list,
                                           "customContextMenuRequested"):
            _s_list.customContextMenuRequested.connect(
                self._on_session_list_menu)
            _s_list.itemSelectionChanged.connect(
                self._refresh_session_spacing_gate)
        _sp_btn = getattr(ui, "session_set_spacing_btn", None)
        if _sp_btn is not None:
            _sp_btn.clicked.connect(self._on_set_spacing)
        # R6: a Patches row's ⓘ opens the model details window
        _info = getattr(ui, "info_requested", None)
        if _info is not None:
            _info.connect(self._on_pr_info_requested)
        try:
            ui._curation_bucket.setContextMenuPolicy(Qt.CustomContextMenu)
            ui._curation_bucket.customContextMenuRequested.connect(
                self._on_curation_list_menu)
        except Exception:      # noqa: BLE001 -- a fake ui
            pass
        self._refresh_pr_foot_gates()
        # n_cpu warning
        ui.n_cpu_sb.valueChanged.connect(self._warn_high_ncpu)
        # Start from (R2a): the one writer; a hand edit flips
        # the list to Custom.  The hidden epicycle_defaults_btn keeps the
        # wrapper; the hidden useg3d_defaults_btn is connected to nothing.
        _sf = getattr(ui, "start_from_combo", None)
        if _sf is not None:
            _sf.activated.connect(self._on_start_from_chosen)
            self._connect_pr_setting_edits()
        # R2b: the cell width's two lines follow the width and the rows
        ui.diameter_sb.valueChanged.connect(self._on_cell_width_changed)
        ui._patch_state_list.itemSelectionChanged.connect(
            self._on_cell_width_changed)
        ui.epicycle_defaults_btn.clicked.connect(
            self._on_epicycle_defaults_clicked)
        # View
        ui.view_reconstructed_button.clicked.connect(self._view_reconstruction)
        # Curation — patch selection for QC view switching
        ui._curation_bucket.itemClicked.connect(self._on_curation_patch_clicked)
        ui.open_3d_annotator_button.clicked.connect(self._open_3d_curation_annotator)
        # 2026-05-17 fix: handle BOTH _curation_dirty AND _tiers_dirty when the
        # user clicks Save (wiring it to _save_curation directly left tier-only
        # changes unsaved — the button stayed lit because _tiers_dirty was
        # never cleared).
        # 2026-06-07: wire to the dedicated ASYNC click handler so the slow
        # mask TIFF write runs off the main thread (no UI freeze).  The handler
        # launches the async mask save (_save_curation_async) + saves the
        # cheap tier CSV synchronously.  The GATE callers (Accept / Finalize /
        # patch-switch guard) still use the SYNCHRONOUS _save_curation_checked /
        # _save_curation so their bool result reflects the completed write.
        ui.save_curation_btn.clicked.connect(self._on_save_curation_clicked)
        ui.undo_curation_btn.clicked.connect(self._undo_last_curation)
        ui.accept_annotation_button.clicked.connect(self._on_3d_curation_accept)
        ui.finalize_labels_button.clicked.connect(self._finalize_curation)
        ui.reset_to_predicted_btn.clicked.connect(self._on_reset_to_predicted)
        # QC — settings dialog + extraction
        ui.qc_settings_btn.clicked.connect(self._open_qc_settings)
        # QC — extraction (scope combo removed 2026-05-03 with
        # drop-population-mode; only single-patch scope remains).
        ui.extract_features_btn.clicked.connect(self._extract_features_current)
        ui.extract_all_features_btn.clicked.connect(self._extract_features_all)
